import{_ as i,o as a,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Running Teuthology Outside of the Sepia lab With Deepshikha Singh","description":"","frontmatter":{"title":"Running Teuthology Outside of the Sepia lab With Deepshikha Singh","date":"2026-01-15T00:00:00.000Z","updated":"2026-01-16T00:00:00.000Z","tags":["Teuthology","Ceph testing","OpenStack","CI/CD","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Running_Teuthology_Outside_of_the_Sepia_lab_With_Deepshikha_Singh.md","filePath":"posts/2026/Running_Teuthology_Outside_of_the_Sepia_lab_With_Deepshikha_Singh.md","lastUpdated":1780459816000}'),o={name:"posts/2026/Running_Teuthology_Outside_of_the_Sepia_lab_With_Deepshikha_Singh.md"};function s(n,e,p,r,h,u){return a(),t("div",null,[...e[0]||(e[0]=[l(`<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次分享由 Deepshikha Singh 主讲，介绍了如何在 Sepia 实验室之外的自有 OpenStack 环境中运行 Teuthology 测试框架。核心目标不是引入新的工作流，而是让各团队能够使用自己的基础设施执行与 Sepia 实验室（CPI）相同的测试套件。</p><h2 id="执行流程" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程" aria-label="Permalink to &quot;执行流程&quot;">​</a></h2><p>Teuthology 从一个专用的控制 VM 运行，该 VM 承载 dispatcher 和编排逻辑。Supervisor 节点在基础设施 VM 上动态 provision，用于触发测试套件（suite）和任务（job）。</p><p>从测试角度来看，测试套件的执行方式与在 CPI 中完全一致，区别仅在于运行在虚拟机而非真实硬件上。任务完成后，结果和日志会归档到 archive 目录，并通过 Pulpito 对外提供访问，保持与上游一致的可见性体验。</p><p><strong>当前已知限制：</strong></p><ul><li>Power cycle 相关测试不支持（需要 IPMI 硬件支持）</li><li>Ceph store（BlueStore）基于真实磁盘的测试不支持（需要物理磁盘）</li><li>上述限制在近期内预计不会解除，因为这些测试本质上依赖真实硬件</li></ul><h2 id="基础设施前提条件" tabindex="-1">基础设施前提条件 <a class="header-anchor" href="#基础设施前提条件" aria-label="Permalink to &quot;基础设施前提条件&quot;">​</a></h2><p>启动前需满足以下条件：</p><ul><li>拥有可用的 OpenStack 项目及有效凭据</li><li>Teuthology 依赖以下标准 OpenStack 服务： <ul><li><strong>Keystone</strong>：认证（authentication）</li><li><strong>Nova</strong>：计算资源</li><li><strong>Neutron</strong>：网络</li><li><strong>Cinder</strong>：存储卷</li></ul></li><li>一台控制 VM 用于托管服务</li><li>网络需正确配置，包括 security group 和 floating IP（实例需要外部访问权限以拉取代码仓库）</li><li>需创建 SSH 密钥对并上传至 OpenStack（Teuthology 用于节点访问）</li></ul><p><strong>基础套件推荐资源配置（最低）：</strong></p><ul><li>24 vCPU</li><li>48 GB RAM</li><li>240磁盘（跨所有 provision 资源合计）</li></ul><h2 id="控制节点配置" tabindex="-1">控制节点配置 <a class="header-anchor" href="#控制节点配置" aria-label="Permalink to &quot;控制节点配置&quot;">​</a></h2><p>控制节点为轻量级 VM，推荐配置如下：</p><ul><li>操作系统：Ubuntu 22.04</li><li>4 vCPU、8 GB RAM、50 GB 磁盘</li><li>随着运行规模扩大，日志存储需求增加，磁盘空间需相应扩展</li></ul><p><strong>配置步骤：</strong></p><ol><li>克隆 Teuthology 代码仓库</li><li>运行 bootstrap 脚本安装依赖</li><li>Teuthology 在 Python 虚拟环境中运行，需激活该环境</li><li>在 <code>clouds.yaml</code> 文件中配置 OpenStack 凭据</li><li>通过 <code>openstack server list</code> 等命令验证访问是否正常</li><li>在 <code>teuthology.yaml</code> 中定义 OpenStack 专属配置，包括 cloud 设置、镜像（image）、规格（flavor）和网络详情</li></ol><h2 id="实际执行流程" tabindex="-1">实际执行流程 <a class="header-anchor" href="#实际执行流程" aria-label="Permalink to &quot;实际执行流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 使用 SSH 密钥和 --setup 参数初始化 Teuthology</span></span>
<span class="line"><span>   （--setup 会自动配置 Pulpito、Padles、PostgreSQL、Beanstalkd 等支撑服务）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 以 OpenStack 模式启动 dispatcher，启用动态 provisioning</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 指定 machine type 为 openstack、Ceph 代码仓库及 job数量上限，触发测试套件</span></span>
<span class="line"><span>   （后续触发时可跳过 --setup 步骤）</span></span></code></pre></div><p>smoke 套件是验证基础功能的推荐起点，至少包含一个 job、最多使用三个节点。</p><h2 id="监控与结果查看" tabindex="-1">监控与结果查看 <a class="header-anchor" href="#监控与结果查看" aria-label="Permalink to &quot;监控与结果查看&quot;">​</a></h2><ul><li><strong>Dispatcher 日志</strong>：用于诊断 provisioning 或调度问题</li><li><strong>Archive 目录</strong>：存储每次运行的详细日志，供深度调试</li><li><strong>Verbose 模式</strong>：执行时加 <code>--verbose</code> 参数可获得更多运行时信息</li><li><strong>Pulpito</strong>：提供高层次的 job 状态、结果和历史运行记录，与上游工作流保持一致</li></ul><p>关于 Pulpito 实例：当前使用的是下游（downstream）自建实例，通过 <code>--setup</code> 参数会在控制节点上自动完成部署。Shaman 目前仍使用上游实例，是否可以覆盖为自建实例尚不确定。</p><h2 id="当前进展与后续计划" tabindex="-1">当前进展与后续计划 <a class="header-anchor" href="#当前进展与后续计划" aria-label="Permalink to &quot;当前进展与后续计划&quot;">​</a></h2><ul><li>正在积极扩大 Teuthology 在 OpenStack 上的测试覆盖范围，增加 job 数量并提升稳定性</li><li>持续改进可复现性（reproducibility），减少测试抖动（flakiness）</li><li><strong>Mass 模式执行</strong>已合并（昨日刚合并），现已支持基于 Mass 的执行模型</li><li><strong>OpenShift 模式执行</strong>已在 PoC 层面完成验证</li><li>正在评估本地和实验室工作流，以改善开发者体验</li><li>探索 PR 触发和分布式 CI 模型，面向更广泛的社区使用</li></ul>`,25)])])}const g=i(o,[["render",s]]);export{d as __pageData,g as default};
